<?php use App\Core\Security; $h=[Security::class,'h']; ?>
<section class="admin-panel"><div class="panel-heading"><div><span>Dados protegidos</span><h2>Inscrições recebidas</h2></div><small>Últimos 200 protocolos</small></div><div class="table-wrap"><table><thead><tr><th>Protocolo</th><th>Profissional</th><th>Projeto</th><th>Revenda / vendedor</th><th>Local</th><th>Data</th><th>Arquivos</th></tr></thead><tbody><?php foreach($registrations as $row): $d=$row['data']; ?><tr><td><code><?= $h($row['reference_code']) ?></code></td><td><strong><?= $h($d['full_name']??'') ?></strong><br><small><?= $h($d['professional_registration']??'') ?> · <?= $h($d['email']??'') ?></small></td><td><?= $h($d['environment_name']??'') ?><br><small><?= $h($d['instagram']??'') ?></small></td><td><?= $h($d['retailer_name']??'') ?><br><small><?= $h($d['seller_name']??'') ?></small></td><td><?= $h(($d['city']??'').' / '.($d['state']??'')) ?></td><td><?= $h(date('d/m/Y H:i',strtotime((string)$row['created_at']))) ?></td><td><button class="text-button" type="button" data-load-files="<?= (int)$row['id'] ?>">Listar arquivos</button><div data-files-for="<?= (int)$row['id'] ?>"></div></td></tr><?php endforeach; ?></tbody></table></div></section>
